ask(c,'After a0=10 and a1=0, which pair of equations determines a2 and a3 for the example?', ['25a2+125a3=60; 10a2+75a3=0','25a2+125a3=70; 10a2+75a3=0','5a2+25a3=60; 2a2+15a3=0','25a2+125a3=60; 25a2+125a3=0'], ['At T=5, subtract a0 from final position and use the differentiated polynomial for final velocity.','The initial 10° contribution must be subtracted.','The first equation would need a divided right-hand side, and the second has the wrong derivative factors.','The velocity equation is not identical to the position-coefficient row.'],difficulty='medium',pages=[497],formula=[CUB],steps=['Position: 70=10+25a2+125a3, so the residual is 60.','Velocity: 0=10a2+75a3.'],assumptions=['Numerical coefficients use degrees and seconds; a2 has deg/s² and a3 has deg/s³.'])
ask(c,'From 10a2+75a3=0 and 25a2+125a3=60, what coefficient pair follows?', ['a2=7.2°/s² and a3=−0.96°/s³','a2=−7.2°/s² and a3=0.96°/s³','a2=7.2°/s² and a3=0.96°/s³','a2=14.4°/s² and a3=−2.88°/s³'], ['a2=−7.5a3; substitution gives −62.5a3=60, then a3=−0.96 and a2=7.2.','Both signs are reversed.','The nonlinear coefficients must have opposite signs for this rest-to-rest move.','These are the velocity-polynomial coefficients, not a2 and a3.'],kind='numerical',difficulty='medium',pages=[497,498],formula=[CUB],steps=['a2=−75a3/10=−7.5a3.','25(−7.5a3)+125a3=−62.5a3=60.','a3=−60/62.5=−0.96°/s³.','a2=−7.5(−0.96)=7.2°/s².'])
ask(c,'Which triple gives the example’s position, velocity and acceleration at 2.5 s?', ['40°, 18°/s, 0°/s²','40°, 0°/s, 18°/s²','70°, 18°/s, 14.4°/s²','10°, 14.4°/s, −5.76°/s²'], ['θ=10+45−15=40; v=36−18=18; a=14.4−14.4=0.','The midpoint velocity is maximal, not zero.','The final position and initial acceleration do not occur at the midpoint.','These confuse initial position and derivative coefficients with midpoint values.'],kind='numerical',difficulty='medium',pages=[498],formula=[EX],steps=['Evaluate θ(2.5)=10+7.2×6.25−0.96×15.625=40°.','Evaluate v(2.5)=14.4×2.5−2.88×6.25=18°/s.','Evaluate a(2.5)=14.4−5.76×2.5=0°/s².'])
ask(c,'Which endpoint acceleration pair belongs to the example?', ['+14.4°/s² at 0 s and −14.4°/s² at 5 s','0°/s² at both endpoints','+18°/s² at both endpoints','−14.4°/s² at 0 s and +14.4°/s² at 5 s'], ['Substitute 0 and 5 into a=14.4−5.76t.','The endpoint velocity is zero, not the endpoint acceleration.','18 is the peak velocity value in °/s, not acceleration.','The acceleration signs are reversed.'],kind='numerical',pages=[498],formula=[EX],steps=['a(0)=14.4°/s².','a(5)=14.4−28.8=−14.4°/s².'])
ask(c,'For the same example, what is θ(1 s), and does the calculation require converting degrees to radians?', ['16.24°; no, not for this consistently degree-based polynomial evaluation','16.24 rad; NumPy always treats polynomial angles as radians','17.2°; the cubic term is omitted at t=1','9.04°; only the negative cubic term contributes'], ['10+7.2−0.96=16.24°, and no trigonometric function is being evaluated.','Plain arithmetic does not assign radians automatically.','The t³ term is nonzero at t=1.','The quadratic contribution is also nonzero.'],kind='numerical',difficulty='medium',pages=[498],formula=[EX],steps=['Insert t=1 s into all three nonzero position terms.','10+7.2−0.96=16.24°.','Consistent coefficient units preserve degrees; trigonometric conversions are not involved.'])
