poly=x0+v0*t+a2*t**2+a3*t**3
for name,expr,expected in [('general initial position',poly.subs(t,0),x0),('general final position',poly.subs(t,T),xf),('general initial velocity',sp.diff(poly,t).subs(t,0),v0),('general final velocity',sp.diff(poly,t).subs(t,T),vf)]:ck(name,sp.simplify(expr-expected),0)
