ck('example endpoint/midpoint positions',tuple(ex.subs(t,z) for z in [0,sp.Rational(5,2),5]),(10,40,70))
ck('example midpoint derivatives',(sp.diff(ex,t).subs(t,sp.Rational(5,2)),sp.diff(ex,t,2).subs(t,sp.Rational(5,2))),(18,0))
ck('example time-one position',ex.subs(t,1),sp.Rational(406,25))
